// Emit one item per label we need to exist. Slash-free category names + Reply-Logged.
const names = ['Positive-Meeting','Interested-Reviewing','Documents-Requested','Questions','Pass','Not-Relevant','Referral-Forwarded','Out-of-Office','Other','Reply-Logged'];
return names.map((n) => ({ json: { labelName: n } }));

const out = [];
const subjRe = /out of office|automatic reply|auto-?reply|on leave|vacation/i;
for (const it of $input.all()) {
  const m = it.json;
  const rawHeaders = m.headers || {};
  const h = {};
  for (const k in rawHeaders) { h[String(k).toLowerCase()] = rawHeaders[k]; }

  let isAuto = false;
  let reason = '';
  const autoSubmitted = h['auto-submitted'];
  if (autoSubmitted !== undefined && autoSubmitted !== null && String(autoSubmitted).trim().toLowerCase() !== 'no') { isAuto = true; reason = 'Auto-Submitted header'; }
  if (!isAuto && (h['x-autoreply'] !== undefined || h['x-autorespond'] !== undefined)) { isAuto = true; reason = 'X-Autoreply/X-Autorespond header'; }
  if (!isAuto && h['precedence'] !== undefined) {
    const p = String(h['precedence']).trim().toLowerCase();
    if (p === 'bulk' || p === 'auto_reply' || p === 'junk') { isAuto = true; reason = 'Precedence: ' + p; }
  }
  const subject = String(m.Subject || m.subject || '');
  if (!isAuto && subjRe.test(subject)) { isAuto = true; reason = 'Subject matched auto-reply pattern'; }

  out.push({ json: {
    messageId: m.id,
    threadId: m.threadId,
    from: m.From || m.from || '',
    subject: subject,
    body: String(m.text || m.snippet || ''),
    is_auto: isAuto,
    auto_reason: reason,
  }});
}
return out;

const tz = 'Asia/Kolkata';
const now = DateTime.now().setZone(tz).toFormat('yyyy-MM-dd HH:mm');
const m = $json;
return { json: {
  timestamp: now,
  workflow: 'Reply-Aditya',
  threadId: m.threadId || '',
  from: m.from || '',
  subject: m.subject || '',
  reason: m.auto_reason || 'auto-reply',
} };

const blank = (x) => x === undefined || x === null || String(x).trim() === '';
const byThread = {};
for (const p of $('Read PIPELINE').all()) {
  const tid = String(p.json.thread_id || '').trim();
  if (tid && byThread[tid] === undefined) byThread[tid] = p.json;
}
const out = [];
for (const it of $input.all()) {
  const m = it.json;
  const tid = String(m.threadId || '').trim();
  const row = tid ? byThread[tid] : undefined;
  let route;
  if (!row) route = 'unmatched';
  else if (!blank(row.investor_response)) route = 'already';
  else route = 'classify';
  out.push({ json: {
    route,
    messageId: m.messageId,
    threadId: m.threadId,
    from: m.from,
    subject: m.subject,
    body: m.body,
    deal_id: row ? row.deal_id : '',
    startup: row ? row.startup : '',
    investor: row ? row.investor : '',
    existing_notes: row ? (row.notes || '') : '',
  }});
}
return out;

const all = $('Read labels final').all();
const wanted = ['Reply-Logged'];
const out = [];
for (const it of $input.all()) { for (const n of wanted) { const f = all.find((l) => String((l.json.name || '')).trim() === n); if (f && f.json.id) out.push({ json: { messageId: it.json.messageId, labelId: f.json.id } }); } }
return out;

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const raw = String(j.textPlain || j.text || j.body || j.snippet || '');
  const subject = String(j.subject || '');
  let body = raw.split(/^\s*On .+ wrote:\s*$/m)[0].split(/^\s*From:\s.+$/m)[0].replace(/^>.*$/gm, '');
  const t = (subject + ' ' + body).toLowerCase().replace(/\s+/g, ' ').trim();
  const has = (...phrases) => phrases.some(p => t.includes(p));
  const re = (pattern) => pattern.test(t);
  let category = 'Other';
  let confidence = 40;
  let matched = 'no clear signal';
  if (has('not a fit', 'not the right fit', 'is not a fit', 'we will pass', 'going to pass', 'have to pass', 'passing on this', 'pass on this', 'pass for now', 'not for us', 'not something we', 'outside our thesis', 'outside our mandate', 'does not fit our', 'not aligned with our', 'unfortunately we', 'we are unable to', 'not pursuing', 'decided not to', 'not moving forward')) {
    category = 'Pass'; confidence = 85; matched = 'explicit pass wording';
  } else if (has('too early for us', 'too early stage', 'we do not invest in', 'we only invest in', 'out of our geography', 'we do not do', 'not our sector', 'wrong stage', 'below our cheque', 'too small for us', 'too large for us')) {
    category = 'Not Relevant'; confidence = 80; matched = 'stage/sector/geography mismatch';
  } else if (has('looping in', 'connecting you with', 'connecting you to', 'forwarded to', 'forwarding this to', 'copying my colleague', 'ccing', 'better person', 'right person', 'the person who covers', 'reach out to my colleague', 'speak to my colleague', 'circulated internally', 'shared internally', 'passed it internally')) {
    category = 'Referral / Forwarded'; confidence = 80; matched = 'referral / internal circulation';
  } else if (has('happy to connect', 'happy to chat', 'happy to meet', 'set up a call', 'schedule a call', 'schedule a meeting', 'book a call', 'calendly', 'my calendar', 'find a time', 'find some time', 'are you free', 'would love to chat', 'would love to connect', 'keen to discuss', 'lets discuss', 'jump on a call', 'hop on a call', 'quick call')) {
    category = 'Positive / Meeting'; confidence = 85; matched = 'meeting request';
  } else if (has('share the deck', 'send the deck', 'send across the deck', 'financial model', 'financials', 'data room', 'dataroom', 'cap table', 'could you share', 'can you share', 'please share', 'send over the', 'share the memo', 'share more details', 'more information on', 'detailed numbers', 'unit economics')) {
    category = 'Documents Requested'; confidence = 75; matched = 'document request';
  } else if (has('looks interesting', 'sounds interesting', 'this is interesting', 'we will review', 'reviewing this', 'taking a look', 'take a look', 'will look into', 'discussing internally', 'discuss internally', 'with the team', 'get back to you', 'revert shortly', 'revert soon', 'come back to you')) {
    category = 'Interested / Reviewing'; confidence = 70; matched = 'interest / under review';
  } else if (re(/\?/) && has('what is', 'what are', 'how much', 'how many', 'who is', 'who are', 'could you clarify', 'can you clarify', 'curious about', 'wondering', 'whats the')) {
    category = 'Questions'; confidence = 70; matched = 'question asked';
  } else if (has('out of office', 'out of the office', 'on leave', 'on vacation', 'annual leave', 'away from my desk', 'currently travelling', 'currently traveling', 'limited access to email')) {
    category = 'Out of Office'; confidence = 90; matched = 'out-of-office wording';
  }
  if (category === 'Other' && body.trim().length < 40) { confidence = 30; matched = 'reply too short to classify'; }
  const firstLine = body.split(/\n/).map(s => s.trim()).filter(s => s.length > 15 && !/^(hi|hello|hey|dear|thanks|thank you|regards|best)\b/i.test(s))[0] || '';
  const summary = (firstLine || body.trim().slice(0, 160)).replace(/\s+/g, ' ').slice(0, 160);
  out.push({ json: { ...j, category, summary: summary || '(no readable text)', confidence, classifier: 'rules-v1', rule_matched: matched } });
}
return out;

const tz = 'Asia/Kolkata';
const today = DateTime.now().setZone(tz).toISODate();
const ext = $json || {};
const ctx = $json;
const labelMap = {
  'Positive / Meeting': 'Positive-Meeting',
  'Interested / Reviewing': 'Interested-Reviewing',
  'Documents Requested': 'Documents-Requested',
  'Questions': 'Questions',
  'Pass': 'Pass',
  'Not Relevant': 'Not-Relevant',
  'Referral / Forwarded': 'Referral-Forwarded',
  'Out of Office': 'Out-of-Office',
  'Other': 'Other',
};
const statusMap = {
  'Pass': 'Passed',
  'Not Relevant': 'Not Relevant',
  'Positive / Meeting': 'Meeting Scheduled',
  'Interested / Reviewing': 'Reviewing',
  'Documents Requested': 'Docs Requested',
  'Questions': 'Questions',
  'Referral / Forwarded': 'Referred',
};
const cat = ext.category;
const conf = Number(ext.confidence);
const summary = String(ext.summary || '');
let doWrite = false, errorLog = false, row = null, errRow = null;
let labelNames = ['Reply-Logged'];
if (!cat || !labelMap[cat]) {
  errorLog = true;
  errRow = { timestamp: today, workflow: 'Reply-Aditya', deal_id: ctx.deal_id, startup: ctx.startup, investor: ctx.investor, error_type: 'CLASSIFY_FAILED', details: 'Extractor returned no/invalid category', resolved: '' };
  labelNames = ['Reply-Logged'];
} else if (cat === 'Out of Office') {
  doWrite = false;
  labelNames = ['Out-of-Office', 'Reply-Logged'];
} else if (isNaN(conf) || conf < 60) {
  doWrite = true;
  row = { deal_id: ctx.deal_id, investor_response: 'Other — needs review', deal_status: 'Needs Review' };
  labelNames = ['Other', 'Reply-Logged'];
} else {
  const notes = (ctx.existing_notes ? ctx.existing_notes + ' | ' : '') + today + ': ' + summary;
  row = { deal_id: ctx.deal_id, investor_response: cat, deal_status: statusMap[cat] || '', next_due: '', notes: notes, last_contact: today };
  doWrite = true;
  labelNames = [labelMap[cat], 'Reply-Logged'];
}
return { json: { messageId: ctx.messageId, deal_id: ctx.deal_id, doWrite, errorLog, row, errRow, labelNames } };

